package com.guardianxr.ar;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.security.*;import java.text.*;import java.util.*;
public class CertificateActivity extends Activity{
 @Override protected void attachBaseContext(Context n){super.attachBaseContext(LocaleUtil.apply(n));}
 public static String id(String module,long ts){try{String s="GXR|"+module+"|"+ts+"|SIH26041";byte[] d=MessageDigest.getInstance("SHA-256").digest(s.getBytes());StringBuilder b=new StringBuilder();for(int i=0;i<6;i++)b.append(String.format("%02X",d[i]));return "GXR-"+b;}catch(Exception e){return "GXR-"+ts;}}
 public void onCreate(Bundle b){super.onCreate(b);String m=getIntent().getStringExtra("module");if(m==null)m="FIRE";long ts=System.currentTimeMillis();String cid=id(m,ts),payload="GUARDIANXR|"+cid+"|"+m+"|PASSED|"+ts;getSharedPreferences("guardianxr",MODE_PRIVATE).edit().putString("cert_"+cid,payload).putString("last_cert",cid).apply();LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setGravity(Gravity.CENTER);l.setPadding(30,40,30,30);l.setBackgroundColor(0xff07101c);TextView h=new TextView(this);h.setText("GuardianXR\n"+getString(R.string.certificate)+"\n\n"+m+" • "+getString(R.string.passed)+"\n"+getString(R.string.certificate_id)+": "+cid+"\n"+new SimpleDateFormat("dd MMM yyyy",Locale.getDefault()).format(new Date(ts))+"\n\n"+getString(R.string.offline_verifiable));h.setTextColor(Color.WHITE);h.setTextSize(19);h.setGravity(Gravity.CENTER);l.addView(h);ImageView q=new ImageView(this);q.setImageBitmap(QrUtil.make(payload,720));l.addView(q,new LinearLayout.LayoutParams(720,720));Button share=new Button(this);share.setText(R.string.share_certificate);String finalCid=cid;share.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,"GuardianXR certificate: "+finalCid);startActivity(Intent.createChooser(i,getString(R.string.share)));});l.addView(share);Button verify=new Button(this);verify.setText(R.string.verify_certificate);verify.setOnClickListener(v->startActivity(new Intent(this,VerifyActivity.class)));l.addView(verify);setContentView(l);}}
